export interface ExportOptions {
  includePdfs: boolean;
  includeAttachments: boolean;
  /** Progress callback: fraction 0..1 and human message. */
  onProgress?: (fraction: number, message: string) => void;
}

export interface ExportResult {
  blob: Blob;
  filename: string;
  fileCount: number;
  csvCount: number;
  bytes: number;
}

function safeFilename(name: string): string {
  // Windows-safe: no path separators, no control chars.
  return name
    .replace(/[<>:"/\\|?*�-]/g, '_')
    .replace(/\.+$/, '')
    .trim();
}

async function readAllForBusiness<T>(
  table: Table<T, string>,
  businessId: string,
): Promise<T[]> {
  return table.where('business_id').equals(businessId).toArray();
}

function jsonStringify(v: unknown): string {
  return typeof v === 'string' ? v : JSON.stringify(v ?? '');
}

function toCsvRow(record: Record<string, unknown>, columns: string[]): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const c of columns) {
    const v = record[c];
    // Nested objects/arrays get JSON-encoded — spec-compat and human-inspectable.
    if (v !== null && typeof v === 'object' && !(v instanceof Date)) {
      out[c] = jsonStringify(v);
    } else {
      out[c] = v;
    }
  }
  return out;
}

async function csvEntry(
  name: string,
  rows: unknown[],
  columns: string[],
): Promise<ZipEntryInput> {
  const body = writeCsv(
    rows.map((r) => toCsvRow(r as Record<string, unknown>, columns)),
    columns,
    { bom: true },
  );
  return { path: `current/${name}.csv`, content: body };
}

function readmeText(business: Business, opts: ExportOptions): string {
  return `BusinessVault — Full Export for ${business.name}
Generated: ${new Date().toISOString()}
Schema version: ${SCHEMA_VERSION}

This ZIP is the customer-owned durable export of your business.
It can be inspected without our service:

  README.txt         This file.
  manifest.json      Business identity, counts, schema version.
  schema.json        Declared schema version — matches manifest.
  current/*.csv      Latest snapshot of every entity (UTF-8, RFC-4180).
                     Money columns are integer paise (₹1 = 100 paise).
                     Quantity columns ending _micros are 6-decimal fixed point.
  metadata/          Audit log CSV.
${opts.includePdfs ? '  invoices/*.pdf     Generated invoice PDFs.\n' : ''}${opts.includeAttachments ? '  attachments/       Uploaded purchase/expense/product files.\n' : ''}
CSV columns are stable. Cells beginning with =, +, -, or @ have been
prefixed with a single quote to prevent spreadsheet formula injection.

To restore your business on a new device:
  1. Install BusinessVault.
  2. Connect the same Google Drive account.
  3. Use "Restore from Google Drive".

You do NOT need BusinessVault to read this data — Excel, Google Sheets,
LibreOffice, or any CSV tool can open it.
`;
}

async function collectAllTables(businessId: string): Promise<Record<string, unknown[]>> {
  const [
    customers, suppliers, items, categories, units, warehouses,
    invoices, invoice_lines, purchases, purchase_lines, payments,
    expenses, stock_movements, accounts, journal_entries, journal_lines,
    audit_log,
  ] = await Promise.all([
    readAllForBusiness(db.customers, businessId),
    readAllForBusiness(db.suppliers, businessId),
    readAllForBusiness(db.items, businessId),
    readAllForBusiness(db.categories, businessId),
    readAllForBusiness(db.units, businessId),
    readAllForBusiness(db.warehouses, businessId),
    readAllForBusiness(db.invoices, businessId),
    readAllForBusiness(db.invoice_lines, businessId),
    readAllForBusiness(db.purchases, businessId),
    readAllForBusiness(db.purchase_lines, businessId),
    readAllForBusiness(db.payments, businessId),
    readAllForBusiness(db.expenses, businessId),
    readAllForBusiness(db.stock_movements, businessId),
    readAllForBusiness(db.accounts, businessId),
    readAllForBusiness(db.journal_entries, businessId),
    readAllForBusiness(db.journal_lines, businessId),
    readAllForBusiness(db.audit_log, businessId),
  ]);
  return {
    customers, suppliers, items, categories, units, warehouses,
    invoices, invoice_items: invoice_lines,
    purchases, purchase_items: purchase_lines,
    payments, expenses, stock_movements, accounts,
    journal_entries, journal_lines,
    orders: [], returns: [],
    audit_log,
  };
}

export async function exportBusinessZip(
  businessId: string,
  opts: ExportOptions,
): Promise<ExportResult> {
  const business = await db.businesses.get(businessId);
  if (!business) throw new Error(`exportBusinessZip: business ${businessId} not found`);
  const report = (f: number, m: string): void => opts.onProgress?.(f, m);

  report(0.0, 'Reading business data');
  const tables = await collectAllTables(businessId);

  report(0.4, 'Generating CSV files');
  const entries: ZipEntryInput[] = [];
  const recordCounts: Record<string, number> = {};
  const csvNames = Object.keys(COLUMNS);
  for (const name of csvNames) {
    const rows = tables[name] ?? [];
    recordCounts[name] = rows.length;
    if (name === 'audit_log') {
      entries.push({
        path: `metadata/audit_log.csv`,
        content: writeCsv(
          rows.map((r) => toCsvRow(r as Record<string, unknown>, COLUMNS[name])),
          COLUMNS[name],
          { bom: true },
        ),
      });
    } else {
      entries.push(await csvEntry(name, rows, COLUMNS[name]));
    }
  }

  const manifest = {
    application: 'BusinessVault',
    applicationVersion: '0.1.0',
    schemaVersion: SCHEMA_VERSION,
    businessId: business.id,
    businessName: business.name,
    legalName: business.legal_name,
    gstin: business.gstin,
    createdAt: business.created_at,
    exportedAt: new Date().toISOString(),
    financialYear: business.current_financial_year,
    recordCounts,
    includes: {
      pdfs: opts.includePdfs,
      attachments: opts.includeAttachments,
    },
  };
  entries.push({
    path: 'manifest.json',
    content: JSON.stringify(manifest, null, 2),
  });
  entries.push({
    path: 'schema.json',
    content: JSON.stringify({ schemaVersion: SCHEMA_VERSION }, null, 2),
  });
  entries.push({
    path: 'README.txt',
    content: readmeText(business, opts),
  });

  report(0.6, 'Collecting attachments');
  if (opts.includePdfs || opts.includeAttachments) {
    const attachments = await readAllForBusiness(db.attachments, businessId);
    for (const att of attachments as Array<{
      id: string;
      ref_type: string;
      filename: string;
      blob: Blob | null;
    }>) {
      if (!att.blob) continue;
      const isPdf = att.ref_type === 'invoice';
      if (isPdf && !opts.includePdfs) continue;
      if (!isPdf && !opts.includeAttachments) continue;
      const safeName = safeFilename(att.filename || att.id);
      const path = isPdf
        ? `invoices/${safeName}`
        : `attachments/${att.ref_type}/${safeName}`;
      entries.push({ path, content: att.blob });
    }
  }

  report(0.85, 'Building ZIP');
  const blob = await buildZip(entries);

  const filename = `${safeFilename(business.name)}-Full-Export.zip`;
  report(1.0, 'Done');
  return {
    blob,
    filename,
    fileCount: entries.length,
    csvCount: csvNames.length,
    bytes: blob.size,
  };
}

export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  // Revoke a tick later so Safari's download starts before the URL dies.
  setTimeout(() => URL.revokeObjectURL(url), 1_000);
}
